BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DB_PATH = os.path.join(BASE_DIR, "maya_gui.db")


def _connect():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db():
    with _connect() as conn:
        conn.executescript("""
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE COLLATE NOCASE NOT NULL,
            salt TEXT NOT NULL,
            password_hash TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS user_settings (
            user_id INTEGER PRIMARY KEY,
            theme TEXT NOT NULL DEFAULT 'dark',
            animation_intensity TEXT NOT NULL DEFAULT 'medium',
            voice_key TEXT NOT NULL DEFAULT 'hi_female',
            voice_speed INTEGER NOT NULL DEFAULT 0,
            voice_pitch INTEGER NOT NULL DEFAULT 0,
            voice_volume INTEGER NOT NULL DEFAULT 100,
            allow_microphone INTEGER NOT NULL DEFAULT 1,
            allow_app_control INTEGER NOT NULL DEFAULT 1,
            allow_system_control INTEGER NOT NULL DEFAULT 1,
            save_history INTEGER NOT NULL DEFAULT 1,
            remember_me INTEGER NOT NULL DEFAULT 0,
            focus_visual TEXT NOT NULL DEFAULT 'default',
            FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS chats (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            title TEXT NOT NULL DEFAULT 'New Chat',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id INTEGER NOT NULL,
            role TEXT NOT NULL,
            content TEXT NOT NULL,
            created_at TEXT NOT NULL,
            FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE
        );
        """)

        # Safe migration for users who already created maya_gui.db with an older GUI version.
        columns = {row[1] for row in conn.execute("PRAGMA table_info(user_settings)").fetchall()}
        if "focus_visual" not in columns:
            conn.execute("ALTER TABLE user_settings ADD COLUMN focus_visual TEXT NOT NULL DEFAULT 'default'")


def _hash_password(password: str, salt_hex: str) -> str:
    salt = bytes.fromhex(salt_hex)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 200_000)
    return digest.hex()


def create_user(username: str, password: str):
    username = username.strip()
    if len(username) < 3:
        return False, "Username must be at least 3 characters."
    if len(password) < 4:
        return False, "Password must be at least 4 characters."

    salt = secrets.token_hex(16)
    password_hash = _hash_password(password, salt)
    now = datetime.now().isoformat(timespec="seconds")

    try:
        with _connect() as conn:
            cur = conn.execute(
                "INSERT INTO users(username, salt, password_hash, created_at) VALUES (?, ?, ?, ?)",
                (username, salt, password_hash, now),
            )
            user_id = cur.lastrowid
            conn.execute("INSERT INTO user_settings(user_id) VALUES (?)", (user_id,))
        return True, "Account created successfully."
    except sqlite3.IntegrityError:
        return False, "This username already exists."


def authenticate(username: str, password: str):
    with _connect() as conn:
        row = conn.execute(
            "SELECT * FROM users WHERE username = ? COLLATE NOCASE",
            (username.strip(),),
        ).fetchone()
    if not row:
        return None
    candidate = _hash_password(password, row["salt"])
    if hmac.compare_digest(candidate, row["password_hash"]):
        return dict(row)
    return None


def get_settings(user_id: int):
    with _connect() as conn:
        row = conn.execute("SELECT * FROM user_settings WHERE user_id = ?", (user_id,)).fetchone()
        if not row:
            conn.execute("INSERT INTO user_settings(user_id) VALUES (?)", (user_id,))
            row = conn.execute("SELECT * FROM user_settings WHERE user_id = ?", (user_id,)).fetchone()
    return dict(row)


def update_settings(user_id: int, **kwargs):
    allowed = {
        "theme", "animation_intensity", "voice_key", "voice_speed", "voice_pitch",
        "voice_volume", "allow_microphone", "allow_app_control", "allow_system_control",
        "save_history", "remember_me", "focus_visual"
    }
    payload = {k: v for k, v in kwargs.items() if k in allowed}
    if not payload:
        return
    columns = ", ".join(f"{k} = ?" for k in payload)
    values = list(payload.values()) + [user_id]
    with _connect() as conn:
        conn.execute(f"UPDATE user_settings SET {columns} WHERE user_id = ?", values)


def create_chat(user_id: int, title: str = "New Chat") -> int:
    now = datetime.now().isoformat(timespec="seconds")
    with _connect() as conn:
        cur = conn.execute(
            "INSERT INTO chats(user_id, title, created_at, updated_at) VALUES (?, ?, ?, ?)",
            (user_id, title, now, now),
        )
        return cur.lastrowid


def list_chats(user_id: int, search: str = "", limit: int | None = None):
    sql = "SELECT * FROM chats WHERE user_id = ?"
    params = [user_id]
    if search.strip():
        sql += " AND title LIKE ?"
        params.append(f"%{search.strip()}%")
    sql += " ORDER BY updated_at DESC"
    if limit is not None:
        sql += " LIMIT ?"
        params.append(limit)
    with _connect() as conn:
        rows = conn.execute(sql, params).fetchall()
    return [dict(r) for r in rows]


def rename_chat(chat_id: int, user_id: int, title: str):
    title = title.strip() or "New Chat"
    with _connect() as conn:
        conn.execute(
            "UPDATE chats SET title = ?, updated_at = ? WHERE id = ? AND user_id = ?",
            (title, datetime.now().isoformat(timespec="seconds"), chat_id, user_id),
        )


def delete_chat(chat_id: int, user_id: int):
    with _connect() as conn:
        conn.execute("DELETE FROM chats WHERE id = ? AND user_id = ?", (chat_id, user_id))


def add_message(chat_id: int, role: str, content: str):
    now = datetime.now().isoformat(timespec="seconds")
    with _connect() as conn:
        conn.execute(
            "INSERT INTO messages(chat_id, role, content, created_at) VALUES (?, ?, ?, ?)",
            (chat_id, role, content, now),
        )
        conn.execute("UPDATE chats SET updated_at = ? WHERE id = ?", (now, chat_id))


def get_messages(chat_id: int):
    with _connect() as conn:
        rows = conn.execute(
            "SELECT * FROM messages WHERE chat_id = ? ORDER BY id ASC", (chat_id,)
        ).fetchall()
    return [dict(r) for r in rows]


def auto_title_from_message(message: str, max_len: int = 34) -> str:
    text = " ".join(message.strip().split())
    if not text:
        return "New Chat"
    return text if len(text) <= max_len else text[:max_len - 1] + "…"


