def resolve_system_theme(app):
    palette: QPalette = app.palette()
    return "dark" if palette.color(QPalette.ColorRole.Window).lightness() < 128 else "light"


def apply_theme(app, theme: str):
    theme = (theme or "dark").lower()
    if theme == "system":
        theme = resolve_system_theme(app)
    app.setStyleSheet(DARK_QSS if theme == "dark" else LIGHT_QSS)
    return theme


