# The three selected Focus Mode images are embedded directly in gui.py.
# No assets folder or extra image files are required at runtime.
FOCUS_VISUALS_B64 = {
    "default": "",
    "rainbow": "",
    "cosmic": "",
}

FOCUS_VISUAL_NAMES = {
    "default": "Default Orb",
    "rainbow": "Rainbow Orb",
    "cosmic": "Cosmic Vortex",
}

_FOCUS_PIXMAP_CACHE = {}

def focus_pixmap(key: str) -> QPixmap:
    key = key if key in FOCUS_VISUALS_B64 else "default"
    if key not in _FOCUS_PIXMAP_CACHE:
        raw = base64.b64decode(FOCUS_VISUALS_B64[key])
        pix = QPixmap()
        if not pix.loadFromData(raw, "PNG"):
            raise RuntimeError(f"Could not load embedded Focus Mode visual: {key}")
        _FOCUS_PIXMAP_CACHE[key] = pix
    return _FOCUS_PIXMAP_CACHE[key]


# ============================================================
# THREAD WORKER
# ============================================================

class WorkerSignals(QObject):
    result = Signal(object)
    error = Signal(str)
    finished = Signal()


class Worker(QRunnable):
    def __init__(self, fn, *args, **kwargs):
        super().__init__()
        self.fn = fn
        self.args = args
        self.kwargs = kwargs
        self.signals = WorkerSignals()

    @Slot()
    def run(self):
        try:
            result = self.fn(*self.args, **self.kwargs)
            self.signals.result.emit(result)
        except Exception:
            self.signals.error.emit(traceback.format_exc())
        finally:
            self.signals.finished.emit()


def response_text(value):
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        for key in ("text", "reply", "message", "content", "result"):
            if key in value and value[key] is not None:
                return str(value[key])
    return str(value)


# ============================================================
# REACTIVE MAYA VISUALIZER
# ============================================================

class MayaVisualizer(QWidget):
    STATES = {"idle", "listening", "thinking", "speaking"}

    def __init__(self, parent=None):
        super().__init__(parent)
        self.state = "idle"
        self.phase = 0.0
        self.intensity = "medium"
        self.setMinimumSize(560, 560)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.timer = QTimer(self)
        self.timer.timeout.connect(self._tick)
        self.timer.start(30)

    def set_state(self, state: str):
        if state in self.STATES:
            self.state = state
            self.update()

    def set_intensity(self, level: str):
        if level in {"low", "medium", "high"}:
            self.intensity = level

    def _tick(self):
        speed = {
            "idle": 0.012,
            "listening": 0.045,
            "thinking": 0.032,
            "speaking": 0.075,
        }[self.state]
        mult = {"low": 0.65, "medium": 1.0, "high": 1.35}[self.intensity]
        self.phase += speed * mult
        self.update()

    def _state_strength(self):
        return {
            "idle": 0.30,
            "listening": 0.62,
            "thinking": 0.50,
            "speaking": 1.0,
        }[self.state]

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)

        w, h = self.width(), self.height()
        cx, cy = w * 0.50, h * 0.46
        size = min(w, h)
        strength = self._state_strength()

        # deep ambient panel glow
        ambient = QRadialGradient(QPointF(cx, cy), size * 0.58)
        ambient.setColorAt(0.0, QColor(18, 99, 167, int(65 + 50 * strength)))
        ambient.setColorAt(0.42, QColor(42, 44, 122, int(40 + 30 * strength)))
        ambient.setColorAt(1.0, QColor(3, 10, 22, 0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(ambient))
        p.drawEllipse(QPointF(cx, cy), size * 0.58, size * 0.58)

        # base radius purposely huge like chosen reference
        base = size * 0.34
        pulse = 1.0
        if self.state == "listening":
            pulse += 0.025 * math.sin(self.phase * 6)
        elif self.state == "thinking":
            pulse += 0.018 * math.sin(self.phase * 4)
        elif self.state == "speaking":
            pulse += 0.055 * math.sin(self.phase * 9)
        radius = base * pulse

        # orbital rings
        ring_count = 4
        for i in range(ring_count):
            rr = radius * (1.10 + i * 0.13)
            rr += (6 + 8 * strength) * math.sin(self.phase * (2.5 + i * 0.25) + i * 0.7)
            alpha = int(35 + 42 * strength - i * 7)
            pen = QPen(QColor(40, 179, 255, max(alpha, 16)), 1.6 if i < 2 else 1.1)
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(QPointF(cx, cy), rr, rr * (0.92 + i * 0.015))

        # floating particles
        p.setPen(Qt.PenStyle.NoPen)
        particle_count = 28 if self.state != "idle" else 18
        for i in range(particle_count):
            ang = (i / particle_count) * math.tau + self.phase * (0.35 + 0.08 * (i % 3))
            rr = radius * (1.05 + 0.28 * ((i % 5) / 4))
            x = cx + math.cos(ang) * rr
            y = cy + math.sin(ang) * rr * 0.92
            dot = 1.4 + 1.8 * abs(math.sin(self.phase * 3 + i)) * strength
            color = QColor(66, 217, 255, int(80 + 130 * strength)) if i % 2 == 0 else QColor(159, 92, 255, int(70 + 120 * strength))
            p.setBrush(color)
            p.drawEllipse(QPointF(x, y), dot, dot)

        # fluid outer ribbon: multiple organic closed waves
        for layer in range(3):
            path = QPainterPath()
            points = 150
            for i in range(points + 1):
                a = (i / points) * math.tau
                wave = (
                    math.sin(a * 5 + self.phase * (1.6 + layer * 0.25)) * (12 + 15 * strength)
                    + math.sin(a * 3 - self.phase * 1.2 + layer) * (7 + 8 * strength)
                )
                rr = radius * (1.02 + layer * 0.055) + wave
                x = cx + math.cos(a) * rr
                y = cy + math.sin(a) * rr * 0.90
                if i == 0:
                    path.moveTo(x, y)
                else:
                    path.lineTo(x, y)
            path.closeSubpath()
            color = [
                QColor(67, 220, 255, int(120 + 55 * strength)),
                QColor(87, 125, 255, int(95 + 55 * strength)),
                QColor(183, 84, 255, int(65 + 50 * strength)),
            ][layer]
            p.setPen(QPen(color, 3.2 - layer * 0.55))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)

        # horizontal voice energy wave through center
        if self.state != "idle":
            for j in range(3):
                path = QPainterPath()
                left = cx - radius * 1.15
                right = cx + radius * 1.15
                steps = 120
                for i in range(steps + 1):
                    x = left + (right - left) * (i / steps)
                    nx = (x - cx) / radius
                    envelope = max(0.0, 1.0 - abs(nx) * 0.72)
                    amp = (10 + 24 * strength) * envelope * (1.0 - j * 0.16)
                    y = cy + math.sin(i * 0.24 + self.phase * (7.0 + j) + j * 1.4) * amp
                    y += (j - 1) * 7
                    if i == 0:
                        path.moveTo(x, y)
                    else:
                        path.lineTo(x, y)
                wave_color = [
                    QColor(47, 225, 255, int(125 + 80 * strength)),
                    QColor(107, 109, 255, int(100 + 60 * strength)),
                    QColor(211, 85, 255, int(85 + 50 * strength)),
                ][j]
                p.setPen(QPen(wave_color, 1.6 + j * 0.2))
                p.drawPath(path)

        # orb core
        core = radius * 0.56
        core_pulse = core * (1 + 0.025 * strength * math.sin(self.phase * 5.5))
        grad = QRadialGradient(QPointF(cx - core * 0.22, cy - core * 0.25), core * 1.25)
        grad.setColorAt(0.0, QColor(235, 251, 255, 255))
        grad.setColorAt(0.18, QColor(92, 220, 255, 252))
        grad.setColorAt(0.48, QColor(54, 135, 255, 248))
        grad.setColorAt(0.72, QColor(112, 74, 245, 242))
        grad.setColorAt(1.0, QColor(32, 20, 89, 225))
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor(140, 231, 255, 180), 2.2))
        p.drawEllipse(QPointF(cx, cy), core_pulse, core_pulse)

        # liquid highlight on core
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QColor(255, 255, 255, 105), 4.0))
        rect = QRectF(cx - core * 0.78, cy - core * 0.72, core * 1.56, core * 1.22)
        p.drawArc(rect, 28 * 16, 112 * 16)

        # central label and state
        p.setPen(QColor(241, 249, 255))
        title_font = QFont("Segoe UI", 25, QFont.Weight.Bold)
        p.setFont(title_font)
        p.drawText(0, int(cy + radius * 0.86), w, 44, Qt.AlignmentFlag.AlignHCenter, "Maya")

        status = {
            "idle": "Ready",
            "listening": "Listening to you...",
            "thinking": "Thinking...",
            "speaking": "Speaking...",
        }[self.state]
        p.setFont(QFont("Segoe UI", 11, QFont.Weight.Medium))
        p.setPen(QColor(94, 220, 255))
        p.drawText(0, int(cy + radius * 0.86 + 38), w, 30, Qt.AlignmentFlag.AlignHCenter, status)


# ============================================================
# FOCUS MODE - FULL SCREEN VISUAL ONLY
# ============================================================

class FocusModeWindow(QWidget):
    exit_requested = Signal()
    pause_changed = Signal(bool)

    def __init__(self, visual_key="default", intensity="medium", parent=None):
        super().__init__(None)
        self.visual_key = visual_key if visual_key in FOCUS_VISUALS_B64 else "default"
        self.intensity = intensity if intensity in {"low", "medium", "high"} else "medium"
        self.state = "idle"
        self.phase = 0.0
        self.paused = False

        self.setWindowTitle("Maya Focus Mode")
        self.setWindowFlags(Qt.WindowType.Window | Qt.WindowType.FramelessWindowHint)
        self.setCursor(Qt.CursorShape.BlankCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, True)

        self.timer = QTimer(self)
        self.timer.timeout.connect(self._tick)
        self.timer.start(30)

    def set_visual(self, key):
        if key in FOCUS_VISUALS_B64:
            self.visual_key = key
            self.update()

    def set_state(self, state):
        if state in {"idle", "listening", "thinking", "speaking"}:
            self.state = state
            self.update()

    def set_paused(self, paused):
        paused = bool(paused)
        if self.paused == paused:
            return
        self.paused = paused
        if paused:
            self.timer.stop()
        else:
            self.timer.start(30)
        self.pause_changed.emit(paused)
        self.update()

    def toggle_pause(self):
        self.set_paused(not self.paused)

    def _tick(self):
        state_speed = {
            "idle": 0.008,
            "listening": 0.030,
            "thinking": 0.021,
            "speaking": 0.052,
        }.get(self.state, 0.01)
        mult = {"low": 0.65, "medium": 1.0, "high": 1.35}.get(self.intensity, 1.0)
        self.phase += state_speed * mult
        self.update()

    def _state_strength(self):
        return {
            "idle": 0.18,
            "listening": 0.48,
            "thinking": 0.38,
            "speaking": 0.72,
        }.get(self.state, 0.18)

    def _cover_rect(self, pixmap: QPixmap, scale_boost=1.0):
        if pixmap.isNull():
            return QRectF(0, 0, self.width(), self.height())
        sw, sh = pixmap.width(), pixmap.height()
        ww, wh = max(1, self.width()), max(1, self.height())
        scale = max(ww / sw, wh / sh) * scale_boost
        dw, dh = sw * scale, sh * scale
        return QRectF((ww - dw) / 2.0, (wh - dh) / 2.0, dw, dh)

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        p.fillRect(self.rect(), QColor(0, 3, 12))

        pix = focus_pixmap(self.visual_key)
        strength = self._state_strength()
        pulse = 1.0
        if not self.paused:
            pulse += (0.004 + strength * 0.009) * math.sin(self.phase * (4.0 + strength * 4.0))
        target = self._cover_rect(pix, pulse)
        p.drawPixmap(target, pix, QRectF(pix.rect()))

        # No text or controls are drawn in Focus Mode. Only visual effects.
        cx, cy = self.width() * 0.5, self.height() * 0.50
        size = min(self.width(), self.height())

        if not self.paused:
            # Subtle breathing aura tied to listening/speaking state.
            aura = QRadialGradient(QPointF(cx, cy), size * 0.62)
            if self.visual_key == "rainbow":
                c1, c2 = QColor(255, 174, 35, int(20 + 65 * strength)), QColor(80, 120, 255, 0)
            elif self.visual_key == "cosmic":
                c1, c2 = QColor(183, 75, 255, int(28 + 78 * strength)), QColor(45, 5, 90, 0)
            else:
                c1, c2 = QColor(42, 212, 255, int(25 + 75 * strength)), QColor(30, 35, 170, 0)
            aura.setColorAt(0.0, c1)
            aura.setColorAt(1.0, c2)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(aura))
            p.drawEllipse(QPointF(cx, cy), size * 0.62, size * 0.62)

            # Very light sci-fi pulse rings to make a still image feel alive.
            if self.state in {"listening", "speaking", "thinking"}:
                ring_color = {
                    "default": QColor(65, 225, 255, int(55 + 70 * strength)),
                    "rainbow": QColor(255, 212, 84, int(45 + 65 * strength)),
                    "cosmic": QColor(210, 100, 255, int(50 + 75 * strength)),
                }[self.visual_key]
                p.setBrush(Qt.BrushStyle.NoBrush)
                for i in range(3):
                    rr = size * (0.22 + i * 0.065) + math.sin(self.phase * 5.0 + i) * (5 + 10 * strength)
                    p.setPen(QPen(ring_color, 1.2 + 0.5 * strength))
                    p.drawEllipse(QPointF(cx, cy), rr, rr)

        if self.paused:
            # Paused is shown only by a visual dim/freeze — never by text.
            p.fillRect(self.rect(), QColor(0, 0, 0, 105))

    def keyPressEvent(self, event):
        key = event.key()
        if key in (Qt.Key.Key_Escape, Qt.Key.Key_F11):
            self.exit_requested.emit()
            event.accept()
            return
        if key == Qt.Key.Key_Space:
            self.toggle_pause()
            event.accept()
            return
        super().keyPressEvent(event)

    def mousePressEvent(self, event):
        # User requested any mouse button to exit Focus Mode.
        self.exit_requested.emit()
        event.accept()

    def showEvent(self, event):
        super().showEvent(event)
        self.activateWindow()
        self.raise_()
        self.setFocus(Qt.FocusReason.ActiveWindowFocusReason)


