class LoginWindow(QWidget):
    login_success = Signal(dict)

    def __init__(self):
        super().__init__()
        self.setWindowTitle("Maya - Login")
        self.resize(760, 720)
        self.setMinimumSize(640, 620)

        root = QVBoxLayout(self)
        root.setContentsMargins(110, 56, 110, 56)
        root.setSpacing(16)

        logo = QLabel("◉")
        logo.setAlignment(Qt.AlignmentFlag.AlignCenter)
        logo.setStyleSheet("font-size: 42px; color: #32d4ff; font-weight: 800;")
        root.addWidget(logo)

        title = QLabel("Maya")
        title.setObjectName("HeroTitle")
        title.setAlignment(Qt.AlignmentFlag.AlignCenter)
        root.addWidget(title)

        sub = QLabel("Your Personal AI Assistant")
        sub.setObjectName("Muted")
        sub.setAlignment(Qt.AlignmentFlag.AlignCenter)
        root.addWidget(sub)
        root.addSpacing(10)

        self.stack = QStackedWidget()
        self.stack.addWidget(self._login_page())
        self.stack.addWidget(self._create_page())
        root.addWidget(self.stack, 1)

    def _card_shadow(self, widget):
        shadow = QGraphicsDropShadowEffect(widget)
        shadow.setBlurRadius(36)
        shadow.setOffset(0, 8)
        shadow.setColor(QColor(0, 120, 210, 70))
        widget.setGraphicsEffect(shadow)

    def _login_page(self):
        page = QFrame()
        page.setObjectName("Panel")
        self._card_shadow(page)
        lay = QVBoxLayout(page)
        lay.setContentsMargins(34, 32, 34, 32)
        lay.setSpacing(15)

        h = QLabel("Welcome back")
        h.setObjectName("Title")
        lay.addWidget(h)

        hint = QLabel("Sign in to continue to Maya")
        hint.setObjectName("Muted")
        lay.addWidget(hint)
        lay.addSpacing(6)

        self.login_user = QLineEdit()
        self.login_user.setPlaceholderText("Username")
        self.login_user.setMinimumHeight(46)
        lay.addWidget(self.login_user)

        self.login_pass = QLineEdit()
        self.login_pass.setPlaceholderText("Password")
        self.login_pass.setEchoMode(QLineEdit.EchoMode.Password)
        self.login_pass.setMinimumHeight(46)
        self.login_pass.returnPressed.connect(self.do_login)
        lay.addWidget(self.login_pass)

        self.remember = QCheckBox("Remember me")
        lay.addWidget(self.remember)

        btn = QPushButton("Login")
        btn.setObjectName("Primary")
        btn.setMinimumHeight(46)
        btn.clicked.connect(self.do_login)
        lay.addWidget(btn)

        create_btn = QPushButton("Create Account")
        create_btn.setMinimumHeight(44)
        create_btn.clicked.connect(lambda: self.stack.setCurrentIndex(1))
        lay.addWidget(create_btn)
        lay.addStretch()
        return page

    def _create_page(self):
        page = QFrame()
        page.setObjectName("Panel")
        self._card_shadow(page)
        lay = QVBoxLayout(page)
        lay.setContentsMargins(34, 32, 34, 32)
        lay.setSpacing(15)

        h = QLabel("Create Account")
        h.setObjectName("Title")
        lay.addWidget(h)

        hint = QLabel("Create a local Maya profile")
        hint.setObjectName("Muted")
        lay.addWidget(hint)
        lay.addSpacing(6)

        self.new_user = QLineEdit()
        self.new_user.setPlaceholderText("Username")
        self.new_user.setMinimumHeight(46)
        lay.addWidget(self.new_user)

        self.new_pass = QLineEdit()
        self.new_pass.setPlaceholderText("Password")
        self.new_pass.setEchoMode(QLineEdit.EchoMode.Password)
        self.new_pass.setMinimumHeight(46)
        lay.addWidget(self.new_pass)

        self.confirm_pass = QLineEdit()
        self.confirm_pass.setPlaceholderText("Confirm Password")
        self.confirm_pass.setEchoMode(QLineEdit.EchoMode.Password)
        self.confirm_pass.setMinimumHeight(46)
        lay.addWidget(self.confirm_pass)

        btn = QPushButton("Create Account")
        btn.setObjectName("Primary")
        btn.setMinimumHeight(46)
        btn.clicked.connect(self.do_create)
        lay.addWidget(btn)

        back = QPushButton("Back to Login")
        back.setMinimumHeight(44)
        back.clicked.connect(lambda: self.stack.setCurrentIndex(0))
        lay.addWidget(back)
        lay.addStretch()
        return page

    def do_login(self):
        user = authenticate(self.login_user.text(), self.login_pass.text())
        if not user:
            QMessageBox.warning(self, "Login failed", "Username or password is incorrect.")
            return
        update_settings(user["id"], remember_me=int(self.remember.isChecked()))
        self.login_success.emit(user)

    def do_create(self):
        if self.new_pass.text() != self.confirm_pass.text():
            QMessageBox.warning(self, "Password", "Passwords do not match.")
            return
        ok, message = create_user(self.new_user.text(), self.new_pass.text())
        if not ok:
            QMessageBox.warning(self, "Create Account", message)
            return
        QMessageBox.information(self, "Create Account", message)
        self.login_user.setText(self.new_user.text().strip())
        self.new_user.clear()
        self.new_pass.clear()
        self.confirm_pass.clear()
        self.stack.setCurrentIndex(0)


